function ref([file,needle]){if(!fs.existsSync(file)){missing.push({file,needle,reason:'arquivo ausente'});return '`'+file+'` (referência pendente)';}const body=fs.readFileSync(file,'utf8'),pos=body.indexOf(needle);if(pos<0){missing.push({file,needle,reason:'trecho ausente'});return `[${file}](<../../../${file}>) (trecho a conferir)`;}const ln=body.slice(0,pos).split('\n').length;return `[${file}:${ln}](<../../../${file}#L${ln}>)`;}
let out='# Catálogo de achados — módulo de academias\n\nAnexo do [diagnóstico](diagnostico-modulo-academias.md). IDs **GYM-AUD** não colidem com backlog GYM. Referências são relativas ao checkout e linhas do snapshot; não houve exploração em dados reais. Severidade técnica e prioridade de execução são distintas; o plano do relatório atribui prioridades/dependências.\n\n| ID | Achado | Categoria | Severidade | Confirmação |\n|---|---|---|---|---|\n';
